package runtime

func dashboardHTML() string {
	return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>vibe-proxy</title><style>
:root{color-scheme:dark;--bg:#07080a;--panel:#0d0f14;--panel2:#11141b;--line:#222631;--muted:#8b93a7;--text:#f5f7fb;--accent:#9b8cff;--accent2:#38bdf8;--good:#22c55e;--bad:#fb7185;--warn:#f59e0b}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 20% 0,#1d1740 0,#07080a 34%),linear-gradient(180deg,#090a0d,#07080a);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}button,input,select,textarea{font:inherit}.shell{max-width:1240px;margin:0 auto;padding:28px}.top{display:flex;justify-content:space-between;gap:20px;align-items:center;margin-bottom:22px}.brand{display:flex;align-items:center;gap:14px}.logo{width:44px;height:44px;border-radius:14px;background:linear-gradient(135deg,var(--accent),var(--accent2));box-shadow:0 0 60px #8b5cf655}.eyebrow{font-size:12px;letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}h1{font-size:28px;margin:0}.muted{color:var(--muted)}.pill{display:inline-flex;align-items:center;gap:8px;border:1px solid var(--line);background:#0b0d12cc;border-radius:999px;padding:8px 12px;color:#cbd5e1}.dot{width:8px;height:8px;border-radius:50%;background:var(--good);box-shadow:0 0 18px var(--good)}.grid{display:grid;grid-template-columns:1.08fr .92fr;gap:18px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.card{border:1px solid var(--line);background:linear-gradient(180deg,#11141bcc,#0b0d12cc);border-radius:22px;padding:20px;box-shadow:0 20px 80px #0008;backdrop-filter:blur(16px)}.mini{padding:16px}.mini b{display:block;margin-bottom:8px}.mono{font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,monospace}.endpoint{font-size:12px;color:#c4b5fd;background:#0b0d12;border:1px solid #2a2f3b;border-radius:10px;padding:8px;overflow:auto}.form{display:grid;gap:12px}.row{display:grid;grid-template-columns:1fr 1fr;gap:12px}.row3{display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px}label{display:grid;gap:6px;color:#cbd5e1;font-size:13px}input,select{width:100%;background:#080a0f;border:1px solid #2a2f3b;color:var(--text);border-radius:12px;padding:11px 12px;outline:none}input:focus,select:focus{border-color:#7c6cff;box-shadow:0 0 0 3px #7c6cff22}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:4px}button{border:0;border-radius:12px;padding:11px 14px;font-weight:700;cursor:pointer;color:#07080a;background:linear-gradient(135deg,#fff,#c7d2fe)}button.secondary{color:#e5e7eb;background:#1b2030;border:1px solid #303747}button.ghost{color:#cbd5e1;background:transparent;border:1px solid #303747}.statusline{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.badge{font-size:12px;border:1px solid #303747;border-radius:999px;padding:5px 9px;color:#cbd5e1;background:#0b0d12}.ok{color:var(--good)}.bad{color:var(--bad)}.warn{color:var(--warn)}pre{white-space:pre-wrap;background:#07090d;border:1px solid var(--line);border-radius:16px;padding:14px;max-height:360px;overflow:auto;color:#dbeafe}.table{width:100%;border-collapse:collapse;font-size:13px}.table th,.table td{text-align:left;border-bottom:1px solid var(--line);padding:10px 8px}.table th{color:var(--muted);font-weight:600}.empty{border:1px dashed #303747;border-radius:16px;padding:18px;color:var(--muted);text-align:center}.span2{grid-column:span 2}@media(max-width:920px){.grid,.row,.row3{grid-template-columns:1fr}.cards{grid-template-columns:1fr}.top{align-items:flex-start;flex-direction:column}.span2{grid-column:auto}}
</style></head><body><main class="shell"><header class="top"><div class="brand"><div class="logo"></div><div><div class="eyebrow">local control plane</div><h1>vibe-proxy</h1><div class="muted">Multi-protocol LLM gateway for local agent workflows.</div></div></div><div class="pill"><span class="dot"></span><span id="health">Checking runtime</span></div></header>
<section class="cards"><div class="card mini"><b>OpenAI Chat</b><div class="endpoint mono">/v1/chat/completions</div></div><div class="card mini"><b>OpenAI Responses</b><div class="endpoint mono">/v1/responses</div></div><div class="card mini"><b>Anthropic Messages</b><div class="endpoint mono">/anthropic/v1/messages</div></div></section>
<div style="height:18px"></div><section class="grid"><div class="card"><div class="statusline"><h2 style="margin:0">Provider Setup</h2><span class="badge">write-through YAML</span><span class="badge">hot reload</span></div><p class="muted">Add a local provider without editing YAML by hand. Secrets are referenced by env var; the key itself is not saved.</p><div class="form"><label>Admin Token<input id="adminToken" placeholder="admin-token"></label><div class="row"><label>Provider ID<input id="providerId" value="newapi"></label><label>Protocol<select id="providerType"><option value="openai-compatible">OpenAI-compatible</option><option value="anthropic">Anthropic</option></select></label></div><label>Base URL<input id="baseUrl" value="http://host.docker.internal:3000/v1"></label><div class="row"><label>API Key Env Var<input id="apiKeyEnv" value="NEW_API_KEY"></label><label>Models<input id="models" value="deepseek-v4-flash,gpt-5.4-mini"></label></div><div class="row3"><label>Alias<input id="alias" value="vibe-chat"></label><label>Alias Target<input id="aliasModel" value="deepseek-v4-flash"></label><label>Default Model<input id="defaultModel" value="vibe-chat"></label></div><div class="actions"><button onclick="configureProvider()">Save & Reload</button><button class="secondary" onclick="testProvider()">Test Provider</button><button class="ghost" onclick="loadAll()">Refresh</button></div></div></div>
<div class="card"><h2 style="margin-top:0">Runtime Snapshot</h2><div id="summary" class="empty">No runtime data loaded yet.</div><div class="actions"><button class="secondary" onclick="validateConfig()">Validate Config</button><button class="ghost" onclick="loadRecent()">Recent Requests</button></div></div>
<div class="card span2"><h2 style="margin-top:0">Recent Requests</h2><div id="recent" class="empty">No requests yet.</div></div><div class="card span2"><h2 style="margin-top:0">Output</h2><pre id="output">Ready.</pre></div></section></main><script>
window.$ = id => document.getElementById(id);
window.printOutput = function(x){ $('output').textContent = typeof x === 'string' ? x : JSON.stringify(x, null, 2); };
window.token = function(){ const v = $('adminToken').value; localStorage.setItem('vibe_admin_token', v); return v; };
window.headers = function(){ return {'Content-Type':'application/json','Authorization':'Bearer '+token()}; };
window.parseResponse = async function(resp){ const text = await resp.text(); try { return JSON.parse(text); } catch { return text; } };
window.api = async function(path, opts = {}){ const resp = await fetch(path, {...opts, headers:{...headers(), ...(opts.headers || {})}}); const body = await parseResponse(resp); if(!resp.ok) throw body; return body; };
window.providerRows = function(s){ const ps = s.providers || []; if(!ps.length) return '<div class="empty">No providers configured yet.</div>'; return '<table class="table"><tr><th>ID</th><th>Type</th><th>Base URL</th><th>Models</th></tr>' + ps.map(p => '<tr><td class="mono">'+p.id+'</td><td>'+p.type+'</td><td class="mono">'+p.base_url+'</td><td>'+(p.models || []).join(', ')+'</td></tr>').join('') + '</table>'; };
window.loadSnapshot = async function(){ const s = await api('/admin/config/snapshot'); $('summary').innerHTML = providerRows(s); printOutput(s); return s; };
window.validateConfig = async function(){ try { printOutput(await api('/admin/config/validate')); } catch(e) { printOutput(e); } };
window.loadRecent = async function(){ try { const r = await api('/admin/requests/recent'); const rows = (r.recent || []).slice(0, 10); $('recent').innerHTML = rows.length ? '<table class="table"><tr><th>Client</th><th>Model</th><th>Provider</th><th>Status</th><th>Tokens</th></tr>' + rows.map(x => '<tr><td>'+x.client_name+'</td><td class="mono">'+x.virtual_model+'</td><td class="mono">'+x.channel_id+'</td><td>'+(x.status_code || '')+'</td><td>'+(x.usage ? x.usage.total_tokens : 0)+'</td></tr>').join('') + '</table>' : '<div class="empty">No requests yet.</div>'; printOutput(r); } catch(e) { printOutput(e); } };
window.configureProvider = async function(){ const payload = {id:$('providerId').value, type:$('providerType').value, base_url:$('baseUrl').value, api_key_env:$('apiKeyEnv').value, models:$('models').value.split(',').map(s => s.trim()).filter(Boolean), alias:$('alias').value, alias_model:$('aliasModel').value, default_model:$('defaultModel').value}; try { const r = await api('/admin/local/configure', {method:'POST', body:JSON.stringify(payload)}); printOutput(r); await loadSnapshot(); } catch(e) { printOutput(e); } };
window.testProvider = async function(){ try { printOutput(await api('/admin/providers/test?id=' + encodeURIComponent($('providerId').value), {method:'POST'})); } catch(e) { printOutput(e); } };
window.health = async function(){ try { const h = await fetch('/healthz').then(r => r.json()); $('health').textContent = 'Running · ' + new Date(h.loaded_at).toLocaleTimeString(); } catch { $('health').textContent = 'Offline'; } };
window.loadAll = async function(){ await health(); try { await loadSnapshot(); } catch(e) { printOutput(e); } await loadRecent().catch(() => {}); };
window.addEventListener('error', e => printOutput('UI error: ' + e.message));
$('adminToken').value = localStorage.getItem('vibe_admin_token') || '';
loadAll();
</script></body></html>`
}
